 const rowEnv={asset,txt,box,line,marker,click};
 function disclosureButton(i,x,y,w=87,h=27,expanded=false){
  const state=expanded?'expanded':'default',label=expanded?'收起':'明细';
  const skin=`<g class="toggle-normal">${asset('v33-toggle-bg-'+state,x,y,w,h,'',true,8)}</g><g class="toggle-hover" style="display:none">${asset('v33-toggle-bg-hover',x,y,w,h,'',true,8)}</g><g class="toggle-pressed" style="display:none">${asset('v33-toggle-bg-pressed',x,y,w,h,'',true,8)}</g>`;
  const arrow=asset('v33-icon-chevron-'+(expanded?'up':'down')+'-light',x+w-27,y+6,16,16,`<path d="M${x+w-24} ${y+(expanded?16:11)}L${x+w-19} ${y+(expanded?11:16)}L${x+w-14} ${y+(expanded?16:11)}" fill="none" stroke="#dedbc9" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/>`);
  return `<g data-action="player-detail-${i}" data-disclosure-player="${i}" role="button" aria-label="${DATA.players[i].name}永续效果明细" aria-expanded="${expanded}" tabindex="0" class="detail-toggle hotspot">${skin}${txt(x+29,y+h/2,label,13,C.ivory,500,'middle')}${arrow}</g>`;
 }
 function scrollControls(zone,x,y,h,scroll,max,viewport,content){
  const arrow=(dir,yy)=>click(zone+'-scroll-'+dir,box(x-7,yy-5,18,18,'#474034','#92816a',.6,3)+`<path d="M${x-3} ${yy+(dir==='up'?5:1)}L${x+2} ${yy+(dir==='up'?1:5)}L${x+7} ${yy+(dir==='up'?5:1)}" stroke="#d4c7af" stroke-width="1.3" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`,dir==='up'?scroll>0:scroll<max);
  const ty=y+20,th=h-40,thumbH=Math.max(30,th*Math.min(1,viewport/content)),travel=th-thumbH,thumbY=ty+(max?scroll/max*travel:0);
  return `<g class="row-scrollbar" data-scrollbar-zone="${zone}" data-scroll-max="${max}" data-thumb-travel="${travel}">${arrow('up',y+5)}${box(x,ty,4,th,'#29231d','none',1,2)}<rect x="${x-6}" y="${ty}" width="16" height="${th}" fill="#000" fill-opacity="0" pointer-events="all" data-scroll-track="${zone}" data-track-top="${ty}" data-track-height="${th}"/><rect x="${x}" y="${thumbY}" width="4" height="${thumbH}" rx="2" fill="#b4a383"/><rect x="${x-6}" y="${thumbY}" width="16" height="${thumbH}" fill="#000" fill-opacity="0" pointer-events="all" data-scroll-thumb="${zone}" role="slider" aria-label="${zone==='detail'?'永续效果':'快速行动'}滚动" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${Math.round(scroll)}" tabindex="0"/>${arrow('down',y+h-12)}</g>`;
 }
 function effectViewport(zone,rows,x,y,w,h,rowH,mode,scrollX){
  const gap=8,content=rows.length*(rowH+gap)-gap,max=Math.max(0,content-h),scroll=Math.max(0,Math.min(max,Number(S[zone+'Scroll'])||0));
  const clipId='effect-clip-'+(++ci);defs.push(`<clipPath id="${clipId}">${box(x,y,w,h,'white')}</clipPath>`);
  const rowsSvg=rows.map((r,i)=>{const rowY=y+i*(rowH+gap)-scroll;let rendered=renderEffectRow({...r,x,y:rowY,w,h:rowH,mode,right:S.effectRowStatus?.[r.id]?{status:S.effectRowStatus[r.id]}:r.right},rowEnv);if(rowY<y||rowY+rowH>y+h)rendered=rendered.replaceAll('tabindex="0"','tabindex="-1"');return rendered;}).join('');
  return `<g data-scroll-zone="${zone}" data-scroll-max="${max}" tabindex="0" role="group" aria-label="${zone==='detail'?'永续效果明细':'快速行动列表'}，可上下滚动">${box(x,y,w,h,'#302a23','none',1,3)}<g clip-path="url(#${clipId})">${rowsSvg}</g>${max?scrollControls(zone,scrollX,y,h,scroll,max,h,content):''}</g>`;
 }
